// Build Weekly Email
// Pulls results from the earlier nodes and assembles ONE short, easy-to-read email.
// It is defensive: if the AI output is shaped differently, or a step failed,
// it still produces a valid email instead of crashing.

function readAI(nodeName) {
  // Read an OpenAI node result no matter which shape n8n returned.
  let j;
  try { j = $(nodeName).item.json; } catch (e) { return {}; }
  let c = j.message?.content ?? j.content ?? j.output ?? j.text ?? j;
  if (typeof c === 'string') {
    try { c = JSON.parse(c); } catch (e) { c = { _raw: c }; }
  }
  return c || {};
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// --- Gather the sheet row (source of truth) ---
let sheet = {};
try { sheet = $('Read Oasis Information').item.json || {}; } catch (e) { sheet = {}; }
const propertyName = sheet['Property name'] || 'Oasis Apartments';
const recipient = sheet['Contact email'] || 'Zalmy@zenithgroupmgmt.com';

// --- Was the website reachable? ---
let websiteChecked = true;
try {
  const page = $('Check Marketing Pages').item.json || {};
  const body = (page.data || page.body || '').toString();
  if (!body || body.length < 30) websiteChecked = false;
} catch (e) { websiteChecked = false; }

// --- Brand check results ---
const brand = readAI('Brand Check');
let issues = Array.isArray(brand.issues) ? brand.issues.slice() : [];
if (!websiteChecked && !issues.some(i => /could not be checked/i.test(i))) {
  issues.push('Website could not be checked automatically this week — please review it by hand.');
}

// --- Posts results ---
const content = readAI('Create Three Posts');
const posts = Array.isArray(content.posts) ? content.posts : [];
const topRec = content.top_recommendation || 'No specific recommendation this week — everything looks on track.';

// --- Merge all open questions ---
let questions = []
  .concat(Array.isArray(brand.questions) ? brand.questions : [])
  .concat(Array.isArray(content.questions) ? content.questions : []);
questions = [...new Set(questions.filter(Boolean))];

// ---------- Build the email ----------
const lines = [];
lines.push(`<h2 style="font-family:Arial,sans-serif;">${esc(propertyName)} — Weekly Marketing Plan</h2>`);

// 1. Things to fix
lines.push('<h3 style="font-family:Arial,sans-serif;">1. Things Zenith Group Should Fix</h3>');
if (issues.length) {
  lines.push('<ul>' + issues.map(i => `<li>${esc(i)}</li>`).join('') + '</ul>');
} else {
  lines.push('<p>No issues found this week. 👍</p>');
}

// 2. Three posts
lines.push("<h3 style=\"font-family:Arial,sans-serif;\">2. This Week's Three Social Posts</h3>");
if (posts.length) {
  for (const p of posts) {
    const checklist = Array.isArray(p.checklist) ? p.checklist : [];
    const tags = Array.isArray(p.hashtags) ? p.hashtags.join(' ') : (p.hashtags || '');
    lines.push('<div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:10px 0;font-family:Arial,sans-serif;">');
    lines.push(`<p><strong>Post ${esc(p.post_number || '')}</strong></p>`);
    lines.push(`<p><strong>Idea:</strong> ${esc(p.idea)}</p>`);
    if (checklist.length) lines.push('<p><strong>Photo/Video checklist:</strong></p><ul>' + checklist.map(c => `<li>${esc(c)}</li>`).join('') + '</ul>');
    lines.push(`<p><strong>Caption:</strong> ${esc(p.caption)}</p>`);
    lines.push(`<p><strong>On-screen text:</strong> ${esc(p.on_screen_text)}</p>`);
    lines.push(`<p><strong>Call to action:</strong> ${esc(p.call_to_action)}</p>`);
    lines.push(`<p><strong>Hashtags:</strong> ${esc(tags)}</p>`);
    lines.push('</div>');
  }
} else {
  lines.push('<p>Posts could not be generated this week. Please re-run the workflow.</p>');
}

// 3. Top recommendation
lines.push('<h3 style="font-family:Arial,sans-serif;">3. One Most Important Recommendation</h3>');
lines.push(`<p>${esc(topRec)}</p>`);

// 4. Questions
lines.push('<h3 style="font-family:Arial,sans-serif;">4. Questions That Need an Answer</h3>');
if (questions.length) {
  lines.push('<ul>' + questions.map(q => `<li>${esc(q)}</li>`).join('') + '</ul>');
} else {
  lines.push('<p>No open questions this week.</p>');
}

const html = lines.join('\n');

// Plain-text version too, for email clients that need it.
const textParts = [];
textParts.push(`${propertyName} — Weekly Marketing Plan\n`);
textParts.push('1. Things Zenith Group Should Fix');
textParts.push(issues.length ? issues.map(i => ' - ' + i).join('\n') : ' No issues found this week.');
textParts.push("\n2. This Week's Three Social Posts");
if (posts.length) {
  for (const p of posts) {
    textParts.push(` Post ${p.post_number || ''}`);
    textParts.push(`  Idea: ${p.idea || ''}`);
    if (Array.isArray(p.checklist)) textParts.push('  Checklist: ' + p.checklist.join('; '));
    textParts.push(`  Caption: ${p.caption || ''}`);
    textParts.push(`  On-screen text: ${p.on_screen_text || ''}`);
    textParts.push(`  Call to action: ${p.call_to_action || ''}`);
    textParts.push(`  Hashtags: ${Array.isArray(p.hashtags) ? p.hashtags.join(' ') : (p.hashtags || '')}`);
    textParts.push('');
  }
} else {
  textParts.push(' Posts could not be generated this week.');
}
textParts.push('3. One Most Important Recommendation');
textParts.push(' ' + topRec);
textParts.push('\n4. Questions That Need an Answer');
textParts.push(questions.length ? questions.map(q => ' - ' + q).join('\n') : ' No open questions this week.');
const text = textParts.join('\n');

return [{ json: { subject: 'Oasis Weekly Marketing Plan', to: recipient, html, text } }];
